import{_ as l,C as i,o as t,c,a2 as a,b as d,w as s,a as p,E as n,a6 as m}from"./chunks/framework.BFzNpupd.js";const E=JSON.parse('{"title":"⚙️ Telematics Engine & Signal Processing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/signal-processing.md","filePath":"guide/signal-processing.md"}'),g={name:"guide/signal-processing.md"};function h(u,e,S,v,_,f){const o=i("Mermaid"),r=i("SchmittHysteresisDiagram");return t(),c("div",null,[e[1]||(e[1]=a('<h1 id="⚙️-telematics-engine-signal-processing" tabindex="-1">⚙️ Telematics Engine &amp; Signal Processing <a class="header-anchor" href="#⚙️-telematics-engine-signal-processing" aria-label="Permalink to &quot;⚙️ Telematics Engine &amp; Signal Processing&quot;">​</a></h1><p>The core telematics pipeline in <code>:speed-core</code> (<code>TelematicsEngine.kt</code>) processes raw GPS fixes through mathematical smoothing and state-machine hysteresis to eliminate false alarms and jitter.</p><hr><h2 id="🔬-mathematical-signal-pipeline" tabindex="-1">🔬 Mathematical Signal Pipeline <a class="header-anchor" href="#🔬-mathematical-signal-pipeline" aria-label="Permalink to &quot;🔬 Mathematical Signal Pipeline&quot;">​</a></h2><p>Raw GPS sensor hardware suffers from multipath reflections, satellite geometry variance, and momentary signal noise. The <code>TelematicsEngine</code> filters raw velocity through three sequential mathematical gates:</p>',5)),(t(),d(m,null,{default:s(()=>[n(o,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%22Raw%20GPS%20Fix%20(Speed%20%26%20Accuracy)%22%5D%20--%3E%20B%7B%22Horizontal%20Accuracy%20Gating%22%7D%0A%20%20%20%20B%20--%3E%7CExceeds%20Uncertainty%20Limit%7C%20C%5B%22Emit%20LowAccuracy%20State%22%5D%0A%20%20%20%20B%20--%3E%7CHigh%20Confidence%20GPS%20Fix%7C%20D%5B%22Exponential%20Moving%20Average%20(EMA)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Smoothed%20Velocity%20Stream%22%5D%0A%20%20%20%20E%20--%3E%20F%7B%22Dual%20Schmitt%20Trigger%20Hysteresis%22%7D%0A%20%20%20%20F%20--%3E%7CUpper%20Threshold%20Exceeded%7C%20G%5B%22Trigger%20Over-Speed%20Alert%22%5D%0A%20%20%20%20F%20--%3E%7CDecelerated%20Below%20Reset%20Delta%7C%20H%5B%22Dismiss%20Over-Speed%20Alert%22%5D%0A%20%20%20%20F%20--%3E%7CWithin%20Legal%20Corridor%7C%20I%5B%22Maintain%20Safe%20Cruising%20State%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_1-gps-confidence-accuracy-gating" tabindex="-1">1. GPS Confidence &amp; Accuracy Gating <a class="header-anchor" href="#_1-gps-confidence-accuracy-gating" aria-label="Permalink to &quot;1. GPS Confidence &amp; Accuracy Gating&quot;">​</a></h2><p>Before any velocity reading is processed, <code>TelematicsEngine</code> validates the horizontal accuracy estimate (2σ precision in meters):</p><div class="tip custom-block"><p class="custom-block-title">🎯 Confidence Validation Gate</p><p>A raw GPS fix is accepted only when:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>horizontalAccuracy &lt;= CONFIDENCE_THRESHOLD (meters, 2σ confidence)</span></span></code></pre></div><p>If the device reports poor satellite geometry (e.g. inside tunnels or urban canyons where accuracy exceeds the threshold), the fix is discarded and the SDK emits <code>SpeedData.LowAccuracy</code>. This prevents inaccurate velocity spikes from sounding alarms.</p></div><hr><h2 id="_2-exponential-moving-average-ema-smoothing" tabindex="-1">2. Exponential Moving Average (EMA) Smoothing <a class="header-anchor" href="#_2-exponential-moving-average-ema-smoothing" aria-label="Permalink to &quot;2. Exponential Moving Average (EMA) Smoothing&quot;">​</a></h2><p>To eliminate erratic velocity jitter from raw GPS sensor readings, the engine applies discrete first-order Exponential Moving Average (EMA) smoothing:</p><div class="tip custom-block"><p class="custom-block-title">📈 Discrete EMA Equation</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SmoothedVelocity[t] = α · RawVelocity[t] + (1 - α) · SmoothedVelocity[t - 1]</span></span></code></pre></div><p>Where <strong>α (alpha)</strong> is a proprietary smoothing coefficient calibrated for optimal balance between gauge responsiveness and jitter suppression. The smoothing calculation is securely executed inside the <code>libveg_vault.so</code> Native C++ engine.</p></div><hr><h2 id="_3-dual-schmitt-trigger-hysteresis" tabindex="-1">3. Dual Schmitt Trigger Hysteresis <a class="header-anchor" href="#_3-dual-schmitt-trigger-hysteresis" aria-label="Permalink to &quot;3. Dual Schmitt Trigger Hysteresis&quot;">​</a></h2><p>To prevent &quot;fluttering&quot; alarms (where an alarm rapidly toggles on and off when driving right at the limit boundary), the SDK implements asymmetric Schmitt Trigger Hysteresis:</p><p>The SDK utilizes a proprietary, asymmetric trigger/dismissal gap to guarantee that an alarm will not flutter.</p><ul><li><strong>Activation:</strong> The over-speed alarm only sounds when smoothed speed crosses a specific delta above the legal limit.</li><li><strong>Dismissal:</strong> Once active, the driver must decelerate a further delta below the limit before the alarm turns off. These exact threshold deltas are secured in the C++ Native Vault.</li></ul>',13)),n(r),e[3]||(e[3]=a('<h3 id="minimum-speed-under-speed-stationary-suppression" tabindex="-1">Minimum Speed (Under-Speed) Stationary Suppression <a class="header-anchor" href="#minimum-speed-under-speed-stationary-suppression" aria-label="Permalink to &quot;Minimum Speed (Under-Speed) Stationary Suppression&quot;">​</a></h3><p>To prevent annoying false under-speed alarms when navigating stoplights, traffic, or speed breakers, the SDK employs <strong>Stationary Suppression</strong>. If the vehicle&#39;s speed drops below a proprietary crawling threshold, the under-speed alarm is aggressively suppressed. It will only fire if the vehicle is actively driving but failing to maintain the legal minimum threshold.</p><hr><h2 id="🚀-non-standard-vehicle-advanced-applications" tabindex="-1">🚀 Non-Standard Vehicle &amp; Advanced Applications <a class="header-anchor" href="#🚀-non-standard-vehicle-advanced-applications" aria-label="Permalink to &quot;🚀 Non-Standard Vehicle &amp; Advanced Applications&quot;">​</a></h2><p>Because <code>TelematicsEngine</code> is pure Kotlin and decoupled from Android UI, it can be applied to non-automotive telematics domains:</p><h3 id="_1-consumer-drones-uavs" tabindex="-1">1. Consumer Drones (UAVs) <a class="header-anchor" href="#_1-consumer-drones-uavs" aria-label="Permalink to &quot;1. Consumer Drones (UAVs)&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Regulations cap drone speeds (e.g., <strong>100 mph</strong> in the US).</li><li><strong>Application:</strong> Drone ground control apps running on Android can pipe UAV telemetry directly into <code>TelematicsEngine</code> using <code>SpeedUnit.MILES_PER_HOUR</code> or <code>SpeedUnit.METERS_PER_SECOND</code> to warn pilots if wind currents push the drone past legal airspeed.</li></ul><h3 id="_2-maritime-marine-boats-jet-skis" tabindex="-1">2. Maritime &amp; Marine (Boats &amp; Jet Skis) <a class="header-anchor" href="#_2-maritime-marine-boats-jet-skis" aria-label="Permalink to &quot;2. Maritime &amp; Marine (Boats &amp; Jet Skis)&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Enforcing &quot;No-Wake Zones&quot; (<strong>&lt; 5 mph</strong>) near harbors and marinas.</li><li><strong>Application:</strong> Marine chartplotters or boat dashboard tablets ingest GPS velocity using <code>SpeedUnit.MILES_PER_HOUR</code> or <code>SpeedUnit.KILOMETERS_PER_HOUR</code> for auditory No-Wake compliance alarms.</li></ul><h3 id="_3-light-aviation-gliders" tabindex="-1">3. Light Aviation &amp; Gliders <a class="header-anchor" href="#_3-light-aviation-gliders" aria-label="Permalink to &quot;3. Light Aviation &amp; Gliders&quot;">​</a></h3><ul><li><strong>Use Case:</strong> Low-altitude gliders and ultralights monitoring maximum airspeed limits and minimum stall speeds.</li><li><strong>Application:</strong> Flight tracking tablets pipe velocity vectors into <code>TelematicsEngine</code> using <code>SpeedUnit.METERS_PER_SECOND</code> or <code>SpeedUnit.FEET_PER_SECOND</code> to provide visual corridor guidance.</li></ul>',11))])}const b=l(g,[["render",h]]);export{E as __pageData,b as default};
